using DarkNights.Content.Assets;
using DarkNights.Simulation;
using Godot;

namespace DarkNights.Presentation.Audio;

/// <summary>
/// 消费会话音频请求并拥有音乐/音效节点的生命周期。受击音效按表现时间限频，静音只影响声音，不修改模拟速度或随机状态。
/// </summary>
public partial class AudioPresenter : Node
{
    private GameSession _session = null!;
    private AssetCatalog _assets = null!;
    [Export] public AudioStreamPlayer Music { get; set; } = null!;
    private double _cooldown;
    public bool Muted { get; private set; }

    public void Initialize(GameSession session, AssetCatalog assets, bool muted)
    {
        _session = session;
        _assets = assets;
        Muted = muted;
        if (!Muted)
            Music.Play();
        _session.Feedback.Sound += PlaySound;
    }

    public override void _Process(double delta) => _cooldown = Math.Max(0, _cooldown - delta);

    public void PlaySound(string name, float volume = -11)
    {
        if (Muted || (_cooldown > 0 && name.Contains("hit")))
            return;
        var stream = _assets.Sound(name);
        if (stream == null)
            return;
        var player = new AudioStreamPlayer { Stream = stream, VolumeDb = volume };
        AddChild(player);
        player.Finished += player.QueueFree;
        player.Play();
        _cooldown = 0.06;
    }

    public void Toggle()
    {
        Muted = !Muted;
        if (Muted)
            Music.Stop();
        else
            Music.Play();
    }

    public override void _ExitTree()
    {
        if (_session != null)
            _session.Feedback.Sound -= PlaySound;
    }
}

using Godot;

namespace DarkNights.Presentation.Authoring;

/// <summary>
/// 保存关卡的玩法标记集合与边界引用，提供编辑辅助而不创建会话。
/// SpawnOrder独立于场景树顺序；预览身份复用既有生成顺序以保持初始服装颜色。
/// </summary>
[Tool]
public partial class LevelLayout : Node2D
{
    [Export] public Marker2D GroundBaseline { get; set; } = null!;
    [Export] public Marker2D WorldEnd { get; set; } = null!;
    [Export] public Marker2D BuildStart { get; set; } = null!;
    [Export] public Marker2D BuildEnd { get; set; } = null!;
    [Export] public Marker2D EnemySpawn { get; set; } = null!;
    [Export] public Marker2D CameraStart { get; set; } = null!;
    [Export] public Node2D Buildings { get; set; } = null!;
    [Export] public Node2D Worksites { get; set; } = null!;
    [Export] public Node2D Actors { get; set; } = null!;
    [Export] public bool ShowGuides { get; set; }

    public static IEnumerable<PlacementMarker> Ordered(Node group) => group.GetChildren()
        .OfType<PlacementMarker>().OrderBy(p => p.SpawnOrder);

    public int PreviewIdentity(PlacementMarker target)
    {
        int id = 1;
        foreach (var marker in Ordered(Buildings).Concat(Ordered(Worksites)).Concat(Ordered(Actors)))
        {
            if (marker == target)
                return id;
            id++;
            if (marker.GetParent() == Buildings && marker.Appearance?.Kind == "farm")
                id++;
        }
        return 0;
    }

    public void EnablePreview()
    {
        foreach (var marker in Ordered(Buildings).Concat(Ordered(Worksites)).Concat(Ordered(Actors)))
        {
            marker.PreviewInGame = true;
            marker.RebuildPreview();
        }
    }

    public override void _Process(double delta)
    {
        if (Engine.IsEditorHint())
        {
            QueueRedraw();
            UpdateConfigurationWarnings();
        }
    }

    public override void _Draw()
    {
        if (!ShowGuides || !Engine.IsEditorHint() || GroundBaseline == null || WorldEnd == null)
            return;
        float y = GroundBaseline.Position.Y;
        DrawLine(new(0, y), new(WorldEnd.Position.X, y), new("b5ccb1"), 0.5f);
        if (BuildStart != null && BuildEnd != null)
            DrawLine(new(BuildStart.Position.X, y + 12), new(BuildEnd.Position.X, y + 12), new("d9c393"), 0.5f);
    }

    public override string[] _GetConfigurationWarnings()
    {
        if (new Node?[] { GroundBaseline, WorldEnd, BuildStart, BuildEnd, EnemySpawn, CameraStart, Buildings, Worksites, Actors }.Any(n => n == null))
            return ["Assign every layout boundary and placement group."];
        var errors = new List<string>();
        foreach (var group in new[] { Buildings, Worksites, Actors })
        {
            var markers = Ordered(group).ToArray();
            if (markers.Select(p => p.SpawnOrder).Distinct().Count() != markers.Length)
                errors.Add($"{group.Name}: SpawnOrder must be unique.");
            if (markers.Any(p => !Mathf.IsEqualApprox(ToLocal(p.GlobalPosition).Y, GroundBaseline.Position.Y)))
                errors.Add($"{group.Name}: align gameplay markers with GroundBaseline.");
        }
        return errors.ToArray();
    }
}

using DarkNights.Presentation.Actors;
