namespace DarkNights.Presentation.Authoring;

/// <summary>
/// 保存一个初始摆放条目的外观引用、顺序与可用参数；位置以脚底为基准。
/// 编辑器只实例化无模型的临时外观，预览节点不设置Owner、不进入存档或生成流程。
/// </summary>
[Tool]
public partial class PlacementMarker : Marker2D
{
    [Export] public VisualDefinition? Appearance { get; set; }
    [Export] public int SpawnOrder { get; set; }
    [Export] public string ActorName { get; set; } = "";
    [Export(PropertyHint.Range, "0,3,1")] public int Variant { get; set; }
    [ExportToolButton("Refresh preview")] public Callable RefreshPreview => Callable.From(RebuildPreview);
    public bool PreviewInGame { get; set; }
    private SceneVisual? _preview;
    private VisualDefinition? _previous;
    private PackedScene? _previousScene;

    public override void _Ready()
    {
        if (Engine.IsEditorHint())
            RebuildPreview();
    }

    public override void _Process(double delta)
    {
        if (!Engine.IsEditorHint() && !PreviewInGame)
            return;
        if (_previous != Appearance || _previousScene != Appearance?.Scene)
            RebuildPreview();
        if (_preview is ActorVisual actor)
        {
            var layout = GetParent()?.GetParent() as LevelLayout;
            actor.SetPose("idle", 0, 1, layout?.PreviewIdentity(this) ?? 0, false, false);
        }
        else if (_preview is WorksiteVisual worksite)
            worksite.SetVariant(Variant, false, false);
        else if (_preview is BuildingVisual building)
            building.SetStage(1);
    }

    public void RebuildPreview()
    {
        if (!Engine.IsEditorHint() && !PreviewInGame)
            return;
        if (_preview != null && GodotObject.IsInstanceValid(_preview))
        {
            RemoveChild(_preview);
            _preview.QueueFree();
        }
        _previous = Appearance;
        _previousScene = Appearance?.Scene;
        _preview = Appearance?.Scene?.Instantiate<SceneVisual>();
        if (_preview != null)
        {
            _preview.Name = "EditorPreview";
            AddChild(_preview);
        }
        UpdateConfigurationWarnings();
    }

    public override string[] _GetConfigurationWarnings()
    {
        if (Appearance == null || Appearance.Scene == null)
            return ["Assign a visual definition. This marker cannot generate a gameplay entity without it."];
        if (Scale != Vector2.One || Rotation != 0)
            return ["Gameplay placements use an unscaled, horizontal ground position."];
        return [];
    }
}

using Godot;

namespace DarkNights.Presentation.Effects;

/// <summary>
/// 显示右键命令的短暂椭圆反馈，参数来自可复用场景。
/// 它不执行移动或选取，销毁时不回调模拟，因此丢失效果不影响命令结果。
/// </summary>
[Tool]
public partial class CommandRing : TimedEffect
{
    [Export] public Color RingColor { get; set; } = new(0.9f, 0.84f, 0.56f);
    [Export] public float InitialRadius { get; set; } = 5;
    [Export] public float ExpansionSpeed { get; set; } = 10;
    [Export] public float Flatten { get; set; } = 0.35f;
    [Export] public float LineWidth { get; set; } = 1;

    public override void _Draw()
    {
        DrawSetTransform(Vector2.Zero, 0, new(1, Flatten));
        DrawArc(Vector2.Zero, InitialRadius + (float)Age * ExpansionSpeed, 0, Mathf.Tau, 20,
            new Color(RingColor, RingColor.A * (float)Math.Clamp(1 - Age / Lifetime, 0, 1)), LineWidth);
        DrawSetTransform(Vector2.Zero);
    }
}

using DarkNights.Content;
using Godot;

namespace DarkNights.Presentation.Effects;

/// <summary>
/// 参数化绘制伤害或产出飘字，保留原有小字号基线、漂移与图标排列。
/// 字体、色彩及图标直接引用场景资源，文本来自一次性通知，不进行结算。
/// </summary>
[Tool]
public partial class FloatingTextView : TimedEffect
{
    [Export] public Font Font { get; set; } = null!;
    [Export] public int FontSize { get; set; } = 7;
    [Export] public Color ResourceColor { get; set; } = new("c6dba3");
    [Export] public Color EnemyColor { get; set; } = new("e8dac1");
    [Export] public Color FriendlyColor { get; set; } = new("ef9582");
    [Export] public Texture2D[] ResourceIcons { get; set; } = [];
    [Export] public string SampleText { get; set; } = "-5";
    [Export] public bool SampleResource { get; set; }
    [Export] public int SampleIcon { get; set; }
    [Export] public float RiseSpeed { get; set; } = 10;

    public override void _Draw()
    {
        if (Font == null)
            return;
        bool resource = Cue?.Kind == "resource" || Cue == null && SampleResource;
        Color color = resource ? ResourceColor : Cue?.Enemy == true ? EnemyColor : FriendlyColor;
        color.A *= (float)Math.Clamp((Lifetime - Age) * 2, 0, 1);
        float drift = Mathf.Sin((Cue?.X ?? GlobalPosition.X) * 3.7f + (Cue?.Y ?? GlobalPosition.Y)) * 5;
        Vector2 at = new(-5 + drift, -(float)Age * RiseSpeed);
        DrawString(Font, at, Cue?.Text ?? SampleText, HorizontalAlignment.Left, -1, FontSize, color);
        if (resource && ResourceIcons.Length > 0)
        {
            int index = Cue == null ? SampleIcon : GameText.ResourceIds.IndexOf(Cue.ContentId);
            var icon = ResourceIcons[Math.Clamp(index, 0, ResourceIcons.Length - 1)];
            DrawTextureRect(icon, new(at + new Vector2(10, -6), new Vector2(8, 8)), false, new(1, 1, 1, color.A));
        }
    }
}

using DarkNights.Simulation.Entities;
using Godot;

namespace DarkNights.Presentation.Effects;

/// <summary>
/// 用箭矢场景显示现有投射物轨迹，模型年龄决定位置与朝向。
/// 图片和原点可编辑，弧线只影响画面；命中时点和伤害始终由ProjectileSystem维护。
/// </summary>
public partial class ProjectileView : Node2D
{
    [Export] public float ArcHeight { get; set; } = 10;
    [Export] public float TangentOffset { get; set; } = 31.4f;

    public void Refresh(Projectile shot)
    {
        float ratio = (float)Math.Clamp(shot.Age / shot.Duration, 0, 1);
        Position = shot.From.Lerp(shot.To, ratio) + new Vector2(0, -Mathf.Sin(ratio * Mathf.Pi) * ArcHeight);
        Vector2 tangent = shot.To - shot.From + new Vector2(0, -Mathf.Cos(ratio * Mathf.Pi) * TangentOffset);
        Rotation = tangent.Angle();
    }
}

