namespace DarkNights.Presentation.Effects;

/// <summary>
/// 从同一外观目录显示尸体或建筑残骸，不保留已死亡模型的引用。
/// 编辑样本使用无Owner的临时外观；动画、原点与残骸图片继续由原外观场景维护。
/// </summary>
[Tool]
public partial class RemnantView : TimedEffect
{
    [Export] public bool Corpse { get; set; } = true;
    [Export] public VisualDefinition Sample { get; set; } = null!;
    [Export] public Color Tint { get; set; } = new(0.75f, 0.75f, 0.75f);
    [Export] public bool FadeAtEnd { get; set; } = true;
    [Export] public Node2D VisualSlot { get; set; } = null!;
    [Export] public bool PreviewLeft { get; set; }
    private VisualDefinition? _appearance;
    private SceneVisual? _visual;

    protected override void Refresh()
    {
        var appearance = Cue == null ? Sample : Catalog!.Find(Corpse ? VisualCategory.Actor : VisualCategory.Building, Cue.ContentId);
        if (VisualSlot == null || appearance == null)
            return;
        if (_appearance != appearance)
        {
            if (_visual != null)
            {
                VisualSlot.RemoveChild(_visual);
                _visual.QueueFree();
            }
            _appearance = appearance;
            _visual = appearance.Scene.Instantiate<SceneVisual>();
            VisualSlot.AddChild(_visual);
        }
        Color tint = Tint;
        if (FadeAtEnd)
            tint.A *= (float)Math.Clamp(Lifetime - Age, 0, 1);
        if (_visual is ActorVisual actor)
            actor.SetPose("die", Age, Cue?.Face ?? (PreviewLeft ? -1 : 1), 0, false, false, tint);
        else if (_visual is BuildingVisual building)
            building.SetStage(1, tint: tint, destroyed: true);
    }
}

using Godot;

namespace DarkNights.Presentation.World;

/// <summary>
/// 用原生Parallax2D重复纹理，并按既有世界原点计算水平视差。
/// Factor与Tint是美术设置；ScrollOffset和运行透明度由环境控制器派生。
/// </summary>
[Tool]
public partial class BackdropLayer : Parallax2D
{
    [Export(PropertyHint.Range, "0,1,0.01")] public float Factor { get; set; } = 0.3f;
    [Export] public Color Tint { get; set; } = Colors.White;
    [Export] public bool FadeWithNight { get; set; }

    public void Apply(float cameraX, float night)
    {
        ScrollOffset = new(cameraX * (1 - Factor), 0);
        Color color = Tint;
        if (FadeWithNight)
            color.A *= night;
        Modulate = color;
    }
}

using Godot;

namespace DarkNights.Presentation.World;

/// <summary>
/// 将场景里的灯光基准与昼夜、闪烁相乘，保持原有亮度和位置相位。
/// 独立打开时提供安全预览，放入关卡后由环境统一传入表现时间。
/// </summary>
[Tool]
public partial class CampLight : PointLight2D
{
    [Export] public float BaseEnergy { get; set; } = 0.65f;
    [Export] public float FlickerAmplitude { get; set; } = 0.07f;
    [Export] public double FlickerFrequency { get; set; } = 3.1;
    [Export] public float PreviewNight { get; set; } = 0.16f;
    public bool ManagedByWorld { get; set; }

    public void Apply(double time, float night) =>
        Energy = night * (BaseEnergy + Mathf.Sin((float)(time * FlickerFrequency + GlobalPosition.X)) * FlickerAmplitude);

    public override void _Process(double delta)
    {
        if (Engine.IsEditorHint() && !ManagedByWorld)
            Apply(0, PreviewNight);
    }
}

using Godot;

namespace DarkNights.Presentation.World;

/// <summary>
/// 按既有公式绘制少量萤火像素，表现时间由环境统一提供。
/// 数量与配色可编辑，不参与昼夜判定，也不影响会话随机序列。
/// </summary>
[Tool]
public partial class Fireflies : Node2D
{
    [Export] public int Count { get; set; } = 15;
    [Export] public float DistributionWidth { get; set; } = 1100;
    [Export] public Color LightColor { get; set; } = new(0.91f, 0.85f, 0.53f);
    [Export] public Vector2 DotSize { get; set; } = new(0.8f, 0.8f);
    private double _time;
    private float _night = 0.16f;

    public void Apply(double time, float night)
    {
        _time = time;
        _night = night;
        QueueRedraw();
    }

    public override void _Draw()
    {
        if (DistributionWidth <= 0)
            return;
        for (int i = 0; i < Count; i++)
        {
            float x = (float)((i * 83.1 + _time * 1.1) % DistributionWidth);
            float y = -15 - (float)(i * 11.3 % 95) + (float)Math.Sin(_time * 0.4 + i) * 3;
            float alpha = (0.15f + _night * 0.5f) * (0.5f + (float)Math.Sin(_time + i * 4.1) * 0.5f);
            DrawRect(new(new(x, y), DotSize), new Color(LightColor, alpha));
        }
    }
}

