namespace DarkNights.Presentation.World;

/// <summary>
/// 参数化绘制原有两圆月牙，颜色和半径可在编辑器调整。
/// 环境传入夜色与镜头位置，本节点不处理游戏时间或关卡状态。
/// </summary>
[Tool]
public partial class MoonView : Node2D
{
    [Export] public Color MoonColor { get; set; } = new(0.89f, 0.88f, 0.72f, 0.65f);
    [Export] public Color DayCutout { get; set; } = new("5e717d");
    [Export] public Color NightCutout { get; set; } = new("263651");
    [Export] public float Radius { get; set; } = 11;
    [Export] public float CutoutRadius { get; set; } = 10;
    [Export] public Vector2 CutoutOffset { get; set; } = new(4, -3);
    [Export] public float CameraOffsetX { get; set; } = 138;
    private float _night = 0.16f;

    public void Apply(float cameraX, float night)
    {
        Position = new(cameraX + CameraOffsetX, Position.Y);
        _night = night;
        QueueRedraw();
    }

    public override void _Draw()
    {
        DrawCircle(Vector2.Zero, Radius, MoonColor);
        DrawCircle(CutoutOffset, CutoutRadius, DayCutout.Lerp(NightCutout, _night));
    }

    public override void _Process(double delta)
    {
        if (Engine.IsEditorHint())
            QueueRedraw();
    }
}

