namespace DarkNights.Presentation.World;

/// <summary>
/// 保留地表下方的固定像素纹理分布，参数仅用于美术显示。
/// 不创建碰撞或地形数据，不使用随机数，因此原有关卡规则与存档保持独立。
/// </summary>
[Tool]
public partial class TerrainDetails : Node2D
{
    [Export] public int Count { get; set; } = 190;
    [Export] public float DistributionWidth { get; set; } = 1100;
    [Export] public Color LightColor { get; set; } = new("3d3a30");
    [Export] public Color DarkColor { get; set; } = new("292820");

    public override void _Draw()
    {
        if (DistributionWidth <= 0)
            return;
        for (int i = 0; i < Count; i++)
        {
            float x = (float)(i * 79.37 % DistributionWidth), y = 14 + (float)(i * 13.81 % 115);
            DrawRect(new(x, y, 2 + i % 4, 1 + i % 2), i % 2 == 0 ? LightColor : DarkColor);
        }
    }

    public override void _Process(double delta)
    {
        if (Engine.IsEditorHint())
            QueueRedraw();
    }
}

