}

using DarkNights.Presentation.Authoring;
using DarkNights.Presentation.Resources;
using DarkNights.Simulation;
using DarkNights.Simulation.State;
using Godot;

namespace DarkNights.Presentation.World;

/// <summary>
/// 绑定关卡里已经序列化的布景、灯光、镜头和布局，按会话状态驱动昼夜表现。
/// 编辑器和独立运行只展示无模型预览；正式会话由组合根注入，环境时间不参与玩法结算。
/// </summary>
[Tool]
public partial class WorldView : Node2D
{
    [Export] public LevelLayout Layout { get; set; } = null!;
    [Export] public EntityViewSynchronizer Entities { get; set; } = null!;
    [Export] public Camera2D SceneCamera { get; set; } = null!;
    [Export] public CanvasModulate Ambient { get; set; } = null!;
    [Export] public Sprite2D Sky { get; set; } = null!;
    [Export] public MoonView Moon { get; set; } = null!;
    [Export] public Fireflies Fireflies { get; set; } = null!;
    [Export] public Node2D GroundEffects { get; set; } = null!;
    [ExportGroup("Day and night")]
    [Export] public Color DayAmbient { get; set; } = new("e9ebde");
    [Export] public Color NightAmbient { get; set; } = new("7187a9");
    [Export] public Color DaySky { get; set; } = new("aabcc1");
    [Export] public Color NightSky { get; set; } = new("465778");
    [Export(PropertyHint.Range, "0,1,0.01")] public float PreviewNight { get; set; } = 0.16f;
    private GameSession? _session;
    private BackdropLayer[] _backdrops = [];
    private CampLight[] _lights = [];
    private TorchView[] _torches = [];
    private double _visualTime;
    public CameraRig Rig { get; private set; } = null!;
    public float NightAmount { get; set; } = 0.16f;

    public override void _Ready()
    {
        var descendants = Descendants(this).ToArray();
        _backdrops = descendants.OfType<BackdropLayer>().ToArray();
        _lights = descendants.OfType<CampLight>().ToArray();
        _torches = descendants.OfType<TorchView>().ToArray();
        foreach (var light in _lights)
            light.ManagedByWorld = true;
        foreach (var torch in _torches)
            torch.ManagedByWorld = true;
        if (!Engine.IsEditorHint() && GetParent() is Window)
            Layout.EnablePreview();
        ApplyEnvironment(SceneCamera?.Position.X ?? 0, PreviewNight);
    }

    public void Initialize(GameSession session, VisualCatalog visuals)
    {
        _session = session;
        Rig = new(SceneCamera, session);
        Entities.Initialize(session, visuals);
        ResetCamera();
    }

    public void ResetCamera()
    {
        NightAmount = 0.16f;
        Rig.Update();
    }

    public override void _Process(double delta)
    {
        if (_session == null)
        {
            if (!Engine.IsEditorHint())
                _visualTime += delta;
            ApplyEnvironment(SceneCamera?.Position.X ?? 0, PreviewNight);
            return;
        }
        _visualTime += delta;
        float target = _session.Waves.Phase == WavePhase.Night ? 1 :
            _session.Waves.DayRemaining < 22 ? (float)((1 - _session.Waves.DayRemaining / 22) * 0.6) : 0.05f;
        if (_session.Mode == SessionMode.Menu)
            target = 0.35f;
        else if (_session.Mode == SessionMode.Won)
            target = 0;
        NightAmount = Mathf.MoveToward(NightAmount, target, (float)(delta * 0.16));
        Rig.Update();
        ApplyEnvironment(_session.Interaction.CameraX, NightAmount);
    }

    public void ApplyEnvironment(float cameraX, float night)
    {
        if (Ambient != null)
            Ambient.Color = DayAmbient.Lerp(NightAmbient, night);
        if (Sky != null)
            Sky.SelfModulate = DaySky.Lerp(NightSky, night);
        foreach (var backdrop in _backdrops)
            backdrop.Apply(cameraX, night);
        foreach (var light in _lights)
            light.Apply(_visualTime, night);
        foreach (var torch in _torches)
            torch.Apply(_visualTime);
        Moon?.Apply(cameraX, night);
        Fireflies?.Apply(_visualTime, night);
    }

    private static IEnumerable<Node> Descendants(Node root)
    {
        foreach (var child in root.GetChildren())
        {
            yield return child;
            foreach (var descendant in Descendants(child))
                yield return descendant;
        }
    }

    public override string[] _GetConfigurationWarnings() =>
        new Node?[] { Layout, Entities, SceneCamera, Ambient, Sky, Moon, Fireflies, GroundEffects }.Any(n => n == null)
            ? ["Assign the level layout, views, camera and environment references."] : [];
}
